class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({ re: {}, cm: {}, dr: {}, er: {}, contactOn: false, ct: '', ctErr: false, toast: '' }, {});
  }
  componentWillUnmount() { clearTimeout(this._tm); }
  say(t) { this.setState({ toast: t }); clearTimeout(this._tm); this._tm = setTimeout(() => this.setState({ toast: '' }), 4200); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o), NB = ' ';
    const fm = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, NB);
    const D = [
      { id: 'marina', name: 'Marina Shore', where: 'Дубай, ОАЭ', tag: 'ГОТОВ', tagCls: 'badge--ok', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1-2 спальни', price: fm(1180000) + NB + 'AED', note: 'Первая линия, рассрочка' },
      { id: 'creek', name: 'Creek Residence', where: 'Дубай, ОАЭ', tag: 'СТРОИТСЯ', tagCls: '', when: 'Сдача в 2027', kind: 'Апартаменты, 1-3 спальни', price: fm(1450000) + NB + 'AED', note: '' },
      { id: 'mira', name: 'Mira Coral Bay', where: 'Рас-эль-Хайма, ОАЭ', tag: 'СТРОИТСЯ', tagCls: '', when: 'Сдача в 2028', kind: 'Апартаменты, 1-3 спальни', price: fm(555000) + NB + 'AED', note: '' }
    ];
    const rows = D.map((o) => {
      const r = S.re[o.id] || '', cs = S.cm[o.id] || [];
      return {
        reAria: 'Ваша реакция: ' + o.name, name: o.name, where: o.where, tag: o.tag, tagCls: o.tagCls, when: o.when, kind: o.kind, price: o.price, agentNote: o.note,
        like: r === 'like', dis: r === 'dis', likeCls: r === 'like' ? 'btn--tint' : '', disCls: r === 'dis' ? 'btn--tint' : '',
        toLike: () => set({ re: Object.assign({}, S.re, { [o.id]: r === 'like' ? '' : 'like' }) }),
        toDis: () => set({ re: Object.assign({}, S.re, { [o.id]: r === 'dis' ? '' : 'dis' }) }),
        hasC: cs.length > 0, comments: cs, fid: 'cm-' + o.id, draft: S.dr[o.id] || '', errCls: S.er[o.id] ? 'is-err' : '',
        onDraft: (e) => set({ dr: Object.assign({}, S.dr, { [o.id]: e.target.value }), er: Object.assign({}, S.er, { [o.id]: false }) }),
        send: () => {
          const t = (S.dr[o.id] || '').trim();
          if (!t) { set({ er: Object.assign({}, S.er, { [o.id]: true }) }); return; }
          set({ cm: Object.assign({}, S.cm, { [o.id]: cs.concat(t) }), dr: Object.assign({}, S.dr, { [o.id]: '' }) });
          this.say('Комментарий отправлен агенту');
        }
      };
    });
    const marked = Object.keys(S.re).filter((k) => S.re[k]).length;
    return {
      rows: rows, n: D.length, marked: marked,
      openContact: () => set({ contactOn: true, ctErr: false }), closeContact: () => set({ contactOn: false }),
      contactOn: S.contactOn, ctText: S.ct, onCt: (e) => set({ ct: e.target.value, ctErr: false }), ctCls: S.ctErr ? 'is-err' : '',
      sendContact: () => { if (!S.ct.trim()) { set({ ctErr: true }); return; } set({ contactOn: false, ct: '' }); this.say('Сообщение отправлено агенту'); },
      toastOn: !!S.toast, toast: S.toast, closeToast: () => set({ toast: '' })
    };
  }
}
